import{_ as a,c as t,a2 as i,o as s}from"./chunks/framework.YPpNXepj.js";const d=JSON.parse('{"title":"Backup Tasks","description":"","frontmatter":{},"headers":[],"relativePath":"backup-tasks.md","filePath":"backup-tasks.md"}'),o={name:"backup-tasks.md"};function r(n,e,l,u,h,p){return s(),t("div",null,e[0]||(e[0]=[i(`<h1 id="backup-tasks" tabindex="-1">Backup Tasks <a class="header-anchor" href="#backup-tasks" aria-label="Permalink to &quot;Backup Tasks&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Backup Tasks are the core functionality of Vanguard. They serve as the central mechanism for defining, organizing, and executing your backups, allowing you to specify what data to protect, its location, and where to store it.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>Before creating a Backup Task, ensure you have:</p><ol><li>At least one <strong>Remote Server</strong> configured - the source of your backup data.</li><li>A <strong>Backup Destination</strong> set up - where your backed-up data will be stored.</li><li>(Optional) <strong>Notification Streams</strong> configured - for receiving alerts about your backup tasks.</li></ol><h2 id="creating-a-backup-task" tabindex="-1">Creating a Backup Task <a class="header-anchor" href="#creating-a-backup-task" aria-label="Permalink to &quot;Creating a Backup Task&quot;">​</a></h2><p>Vanguard offers an intuitive, step-by-step process for creating Backup Tasks:</p><ol><li><p><strong>Specify Details</strong></p><ul><li>Enter a label for your backup task</li><li>Provide a description for easy reference</li><li>Add relevant tags for organization</li></ul></li><li><p><strong>Set Configuration</strong></p><ul><li>Choose the backup destination</li><li>Select the backup type</li><li>Specify the maximum number of backups to retain</li><li>Pick the remote server to pull data from</li></ul></li><li><p><strong>Configure Details</strong></p><ul><li>Enter the path of the directory on the remote server to backup</li><li>Specify the directory on the backup destination for data storage</li><li>(Optional) Configure isolated environment details if required</li></ul></li><li><p><strong>Set Schedule</strong></p><ul><li>Define backup frequency</li><li>Use cron expressions for advanced scheduling options</li></ul></li><li><p><strong>Notifications</strong></p><ul><li>Select which notification streams to use for alerts</li></ul></li><li><p><strong>Save</strong></p><ul><li>Review your settings and save the backup task</li><li>You&#39;ll be redirected to the backup tasks overview, where you can run the task immediately if desired</li></ul></li></ol><h2 id="managing-backup-tasks" tabindex="-1">Managing Backup Tasks <a class="header-anchor" href="#managing-backup-tasks" aria-label="Permalink to &quot;Managing Backup Tasks&quot;">​</a></h2><h3 id="paused-backups" tabindex="-1">Paused Backups <a class="header-anchor" href="#paused-backups" aria-label="Permalink to &quot;Paused Backups&quot;">​</a></h3><p>Backup Tasks that are paused will not be scheduled and cannot be run manually.</p><h3 id="backup-task-history" tabindex="-1">Backup Task History <a class="header-anchor" href="#backup-task-history" aria-label="Permalink to &quot;Backup Task History&quot;">​</a></h3><p>A log is created for every backup task execution, regardless of its outcome, providing a comprehensive audit trail.</p><h2 id="automated-triggering-via-webhook" tabindex="-1">Automated Triggering via Webhook <a class="header-anchor" href="#automated-triggering-via-webhook" aria-label="Permalink to &quot;Automated Triggering via Webhook&quot;">​</a></h2><p>Each Backup Task can be triggered using a secure webhook URL. This feature allows for flexible integration with external systems such as CI/CD pipelines.</p><h3 id="where-is-it" tabindex="-1">Where is it? <a class="header-anchor" href="#where-is-it" aria-label="Permalink to &quot;Where is it?&quot;">​</a></h3><p>The webhook URL can be found by clicking the &#39;View Webhook URL&#39; button located on the &#39;Backup Tasks&#39; page. Click the button to bring up the modal.</p><p>For security, tokens can be re-generated per Backup Task. You will find an option to do this in the modal.</p><h3 id="webhook-request-details" tabindex="-1">Webhook Request Details <a class="header-anchor" href="#webhook-request-details" aria-label="Permalink to &quot;Webhook Request Details&quot;">​</a></h3><ul><li><strong>Method</strong>: POST only</li><li><strong>Authentication</strong>: Token is embedded in the URL itself</li><li><strong>Rate Limit</strong>: 10 requests per minute per backup task</li></ul><h3 id="example-webhook-trigger-curl" tabindex="-1">Example Webhook Trigger (cURL) <a class="header-anchor" href="#example-webhook-trigger-curl" aria-label="Permalink to &quot;Example Webhook Trigger (cURL)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://your-domain.com/webhooks/backup-tasks/123/run?token=your-webhook-token&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Accept: application/json&quot;</span></span></code></pre></div><h3 id="possible-response-scenarios" tabindex="-1">Possible Response Scenarios <a class="header-anchor" href="#possible-response-scenarios" aria-label="Permalink to &quot;Possible Response Scenarios&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Status Code</th><th>Meaning</th></tr></thead><tbody><tr><td>202</td><td>Backup task initiated successfully</td></tr><tr><td>403</td><td>Invalid authentication token</td></tr><tr><td>409</td><td>Task cannot be run (paused or conflicting)</td></tr><tr><td>429</td><td>Rate limit exceeded</td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><p>After creating a Backup Task:</p><ul><li>Run the task manually to verify its configuration</li><li>Monitor its execution in the Vanguard dashboard</li><li>Set up integrations using the webhook if needed</li></ul>`,28)]))}const k=a(o,[["render",r]]);export{d as __pageData,k as default};
